//! Property tests for the hkask-regulation sensor providers.
//!
//! These replace the deleted stub-based tests that faked the `Sensor` trait
//! (the `TestSensor` double with hardcoded values in the old `sensor_provider`
//! `mod tests`). No fake `Sensor` implementations are constructed here. The
//! tests exercise the real `TestCoverageSensor` / `MutationScoreSensor`
//! `metrics.json` extraction logic — the pure parsing path inside `sense()` —
//! over arbitrary JSON content generated by `arb_json_value`, adjudicated
//! through the `hkask-test-harness` Oracle taxonomy (reference + invariant
//! oracles). The private `latest_metrics_path` helper is exercised through the
//! public `sense()` API.
//!
//! Coverage focus:
//! - For arbitrary `metrics.json` content, the sensor returns a signal iff
//!   the numeric target field is present and below the set-point; otherwise
//!   it returns `None` (graceful degradation — never panics).
//! - `latest_metrics_path` selects the most-recently-modified `metrics.json`.
//! - Missing trace dir, empty trace dir, malformed JSON, non-numeric field,
//!   and at/above-set-point values all yield `None`.

use hkask_regulation::sensor_provider::{MutationScoreSensor, Sensor, TestCoverageSensor};
use hkask_regulation::types::loops::{Signal, SignalMetric};
use hkask_test_harness::{
    Oracle, OracleVerdict, arb_json_value, oracle_hardcoded, oracle_invariant, oracle_reference,
};
use proptest::prelude::*;
use serde_json::Value as JsonValue;
use std::path::Path;
use tempfile::TempDir;

/// Run an async `sense()` on a current-thread tokio runtime (proptest!
/// generates a sync `#[test]`, so we block on the future locally).
fn block_on_sense<S: Sensor + ?Sized>(sensor: &S) -> Option<Signal> {
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("tokio runtime");
    rt.block_on(sensor.sense())
}

/// Serialize a `Signal` (or `None`) into the canonical JSON shape the
/// reference oracle compares against: `null` for no signal, or
/// `{"value": v, "set_point": sp, "metric": "<as_str>"}`.
fn signal_to_json(signal: Option<Signal>) -> JsonValue {
    match signal {
        None => JsonValue::Null,
        Some(s) => serde_json::json!({
            "value": s.value,
            "set_point": s.set_point,
            "metric": s.metric.as_str(),
        }),
    }
}

/// Write `contents` to `{trace_dir}/{run_name}/metrics.json`.
fn write_run_metrics(trace_dir: &Path, run_name: &str, contents: &str) {
    let run_dir = trace_dir.join(run_name);
    std::fs::create_dir_all(&run_dir).expect("create run dir");
    std::fs::write(run_dir.join("metrics.json"), contents).expect("write metrics.json");
}

fn assert_pass(oracle: &dyn Oracle, input: &JsonValue, output: &JsonValue) {
    match oracle.verify(input, output) {
        OracleVerdict::Pass => {}
        other => panic!("oracle verdict was {other:?}"),
    }
}

// ── Reference-oracle property tests ────────────────────────────────────────
//
// The reference oracle re-implements the extraction contract independently:
//   signal = Some(value)  iff  metrics["<field>"].as_f64() == Some(c) && c < set_point
//   signal = None          otherwise
// and compares against the sensor's actual output. This cross-checks the
// sensor's JSON path against an independent implementation.

proptest! {
    /// `TestCoverageSensor` extracts `coverage_pct` exactly when the
    /// reference says it should, for arbitrary `metrics.json` content.
    #[test]
    fn coverage_sensor_matches_reference_extraction(
        value in arb_json_value(),
        set_point in 0.0f64..1.0,
    ) {
        let dir = TempDir::new().expect("temp dir");
        let raw = serde_json::to_string(&value).unwrap_or_default();
        write_run_metrics(dir.path(), "run-1", &raw);

        let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), set_point);
        let output_json = signal_to_json(block_on_sense(&sensor));

        let input_json = serde_json::json!({ "metrics": value, "set_point": set_point });
        let oracle = oracle_reference(|input: &JsonValue| -> JsonValue {
            let sp = input.get("set_point").and_then(|v| v.as_f64()).unwrap_or(0.0);
            let metrics = input.get("metrics").unwrap_or(&JsonValue::Null);
            match metrics.get("coverage_pct").and_then(|f| f.as_f64()) {
                Some(c) if c < sp => serde_json::json!({
                    "value": c,
                    "set_point": sp,
                    "metric": SignalMetric::TestCoverage.as_str(),
                }),
                _ => JsonValue::Null,
            }
        });
        assert_pass(&*oracle, &input_json, &output_json);
    }
}

