proptest! {
    /// Invariant: the sensor never panics on arbitrary content, and when it
    /// returns a signal the value is strictly below the set-point and the
    /// metric is `TestCoverage`.
    #[test]
    fn coverage_sensor_signal_invariants(
        value in arb_json_value(),
        set_point in 0.0f64..1.0,
    ) {
        let dir = TempDir::new().expect("temp dir");
        let raw = serde_json::to_string(&value).unwrap_or_default();
        write_run_metrics(dir.path(), "run-1", &raw);

        let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), set_point);
        let output_json = signal_to_json(block_on_sense(&sensor));
        let input_json = serde_json::json!({ "set_point": set_point });

        let oracle = oracle_invariant(|input, output| {
            let sp = input.get("set_point").and_then(|v| v.as_f64()).unwrap_or(0.0);
            if output.is_null() {
                return Ok(());
            }
            let v = output.get("value").and_then(|x| x.as_f64()).unwrap_or(f64::INFINITY);
            let metric = output.get("metric").and_then(|x| x.as_str()).unwrap_or("");
            if v.partial_cmp(&sp) != Some(std::cmp::Ordering::Less) {
                return Err(format!("signal value {v} must be < set_point {sp}"));
            }
            if metric != SignalMetric::TestCoverage.as_str() {
                return Err(format!("metric {metric:?} != test_coverage"));
            }
            Ok(())
        });
        assert_pass(&*oracle, &input_json, &output_json);
    }
}

