// ── latest_metrics_path: most-recently-modified selection ──────────────────

#[test]
fn coverage_sensor_reads_most_recently_modified_metrics() {
    let dir = TempDir::new().expect("temp dir");
    write_run_metrics(dir.path(), "run-old", r#"{"coverage_pct": 0.2}"#);
    // Ensure a strictly newer mtime for run-new (filesystem resolution varies).
    std::thread::sleep(std::time::Duration::from_millis(20));
    write_run_metrics(dir.path(), "run-new", r#"{"coverage_pct": 0.5}"#);

    let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), 0.9);
    let output_json = signal_to_json(block_on_sense(&sensor));
    let oracle = oracle_hardcoded(serde_json::json!({
        "value": 0.5,
        "set_point": 0.9,
        "metric": SignalMetric::TestCoverage.as_str(),
    }));
    assert_pass(&*oracle, &JsonValue::Null, &output_json);
}

#[test]
fn mutation_sensor_reads_most_recently_modified_metrics() {
    let dir = TempDir::new().expect("temp dir");
    write_run_metrics(dir.path(), "run-old", r#"{"mutation_score": 0.1}"#);
    std::thread::sleep(std::time::Duration::from_millis(20));
    write_run_metrics(dir.path(), "run-new", r#"{"mutation_score": 0.4}"#);

    let sensor = MutationScoreSensor::new(dir.path().to_path_buf(), 0.6);
    let output_json = signal_to_json(block_on_sense(&sensor));
    let oracle = oracle_hardcoded(serde_json::json!({
        "value": 0.4,
        "set_point": 0.6,
        "metric": SignalMetric::MutationScore.as_str(),
    }));
    assert_pass(&*oracle, &JsonValue::Null, &output_json);
}

// ── Graceful-degradation scenarios (None, not panic) ────────────────────────

/// Helper: assert the sensor returns `None` for a given `metrics.json` body
/// via an `oracle_hardcoded(Null)` oracle.
fn assert_none(body: &str, make_sensor: impl Fn(std::path::PathBuf) -> Box<dyn Sensor>) {
    let dir = TempDir::new().expect("temp dir");
    if !body.is_empty() {
        write_run_metrics(dir.path(), "run-1", body);
    }
    let sensor = make_sensor(dir.path().to_path_buf());
    let output_json = signal_to_json(block_on_sense(&*sensor));
    assert_pass(
        &*oracle_hardcoded(JsonValue::Null),
        &JsonValue::Null,
        &output_json,
    );
}

#[test]
fn coverage_sensor_missing_trace_dir_returns_none() {
    // No TempDir created at all → the path does not exist.
    let bogus = std::env::temp_dir().join(format!(
        "hkask-regulation-sensor-missing-{}-{}",
        std::process::id(),
        std::thread::current().name().unwrap_or("t").len()
    ));
    let _ = std::fs::remove_dir_all(&bogus);
    let sensor = TestCoverageSensor::new(bogus.clone(), 0.9);
    let output_json = signal_to_json(block_on_sense(&sensor));
    assert_pass(
        &*oracle_hardcoded(JsonValue::Null),
        &JsonValue::Null,
        &output_json,
    );
    let _ = std::fs::remove_dir_all(&bogus);
}

#[test]
fn coverage_sensor_empty_trace_dir_returns_none() {
    let dir = TempDir::new().expect("temp dir");
    // No run subdirs, no metrics.json.
    let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), 0.9);
    let output_json = signal_to_json(block_on_sense(&sensor));
    assert_pass(
        &*oracle_hardcoded(JsonValue::Null),
        &JsonValue::Null,
        &output_json,
    );
}

#[test]
fn coverage_sensor_run_without_metrics_json_returns_none() {
    let dir = TempDir::new().expect("temp dir");
    let run_dir = dir.path().join("run-1");
    std::fs::create_dir_all(&run_dir).expect("create run dir");
    // A run dir exists but has no metrics.json.
    let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), 0.9);
    let output_json = signal_to_json(block_on_sense(&sensor));
    assert_pass(
        &*oracle_hardcoded(JsonValue::Null),
        &JsonValue::Null,
        &output_json,
    );
}

#[test]
fn coverage_sensor_malformed_json_returns_none() {
    assert_none("{not valid json", |p| {
        Box::new(TestCoverageSensor::new(p, 0.9))
    });
}

#[test]
fn coverage_sensor_non_numeric_field_returns_none() {
    assert_none(r#"{"coverage_pct": "high"}"#, |p| {
        Box::new(TestCoverageSensor::new(p, 0.9))
    });
}

#[test]
fn coverage_sensor_field_absent_returns_none() {
    assert_none(r#"{"mutation_score": 0.8}"#, |p| {
        Box::new(TestCoverageSensor::new(p, 0.9))
    });
}

#[test]
fn coverage_sensor_at_or_above_set_point_returns_none() {
    // value == set_point → healthy → None.
    assert_none(r#"{"coverage_pct": 0.9}"#, |p| {
        Box::new(TestCoverageSensor::new(p, 0.9))
    });
    // value > set-point → healthy → None.
    assert_none(r#"{"coverage_pct": 0.99}"#, |p| {
        Box::new(TestCoverageSensor::new(p, 0.7))
    });
}

#[test]
fn mutation_sensor_malformed_json_returns_none() {
    assert_none("<<broken", |p| Box::new(MutationScoreSensor::new(p, 0.5)));
}

#[test]
fn mutation_sensor_field_absent_returns_none() {
    assert_none(r#"{"coverage_pct": 0.8}"#, |p| {
        Box::new(MutationScoreSensor::new(p, 0.5))
    });
}

#[test]
fn mutation_sensor_at_or_above_set_point_returns_none() {
    assert_none(r#"{"mutation_score": 0.5}"#, |p| {
        Box::new(MutationScoreSensor::new(p, 0.5))
    });
    assert_none(r#"{"mutation_score": 0.9}"#, |p| {
        Box::new(MutationScoreSensor::new(p, 0.4))
    });
}

// ── Positive extraction: exact value propagation ───────────────────────────

#[test]
fn coverage_sensor_returns_exact_value_below_set_point() {
    let dir = TempDir::new().expect("temp dir");
    write_run_metrics(dir.path(), "run-1", r#"{"coverage_pct": 0.42}"#);
    let sensor = TestCoverageSensor::new(dir.path().to_path_buf(), 0.7);
    let output_json = signal_to_json(block_on_sense(&sensor));
    let oracle = oracle_hardcoded(serde_json::json!({
        "value": 0.42,
        "set_point": 0.7,
        "metric": SignalMetric::TestCoverage.as_str(),
    }));
    assert_pass(&*oracle, &JsonValue::Null, &output_json);
}

#[test]
fn mutation_sensor_returns_exact_value_below_set_point() {
    let dir = TempDir::new().expect("temp dir");
    write_run_metrics(dir.path(), "run-1", r#"{"mutation_score": 0.33}"#);
    let sensor = MutationScoreSensor::new(dir.path().to_path_buf(), 0.5);
    let output_json = signal_to_json(block_on_sense(&sensor));
    let oracle = oracle_hardcoded(serde_json::json!({
        "value": 0.33,
        "set_point": 0.5,
        "metric": SignalMetric::MutationScore.as_str(),
    }));
    assert_pass(&*oracle, &JsonValue::Null, &output_json);
}
